package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="refinement_iterations") public class RefinementIteration { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="job_id") private AnalysisJob job; @Column(nullable=false) private int iteration; @Column(nullable=false) private String action; @Lob private String feedbackJson; @Column(nullable=false) private Instant createdAt=Instant.now(); public RefinementIteration(){} public RefinementIteration(AnalysisJob j,int i,String a,String f){job=j;iteration=i;action=a;feedbackJson=f;} }
